"""Anno 1503 Auto Trainer V0.11.2 - Transactional Updater V3.1 silent helpers.

Updater-only maintenance release. Python/PyInstaller helper processes are hidden,
compact progress is mirrored to OneDrive, and the working trainer still remains
open until a fully prepared EXE is ready. No gameplay logic changes.
"""
from pathlib import Path
import base64

VERSION = "0.11.2"
UPDATER_B64 = ''


def _replace_exact(path: Path, old: str, new: str, count: int | None = None):
    text = path.read_text(encoding="utf-8")
    actual = text.count(old)
    if actual == 0:
        raise RuntimeError(f"Expected text not found in {path.name}: {old!r}")
    if count is not None and actual != count:
        raise RuntimeError(f"Unexpected occurrence count in {path.name}: {actual} != {count}")
    path.write_text(text.replace(old, new), encoding="utf-8")


def apply(root):
    root = Path(root)
    core = root / "Anno1503_AutoTrainer.py"
    gui = root / "Anno1503_AutoTrainer_GUI.py"
    updater = root / "updater.py"
    for p in (core, gui, updater):
        if not p.is_file():
            raise RuntimeError(f"Required source file missing: {p}")

    if 'TRAINER_VERSION = "0.11.1"' not in core.read_text(encoding="utf-8"):
        raise RuntimeError("V0.11.2 requires V0.11.1 source")
    if 'CURRENT_VERSION = "0.11.1"' not in updater.read_text(encoding="utf-8"):
        raise RuntimeError("V0.11.2 requires V0.11.1 transactional updater base")

    _replace_exact(core, 'TRAINER_VERSION = "0.11.1"', 'TRAINER_VERSION = "0.11.2"', 1)
    ct=core.read_text(encoding="utf-8")
    if ' AUTO TRAINER V0.11.1' in ct:
        core.write_text(ct.replace(' AUTO TRAINER V0.11.1',' AUTO TRAINER V0.11.2'),encoding="utf-8")

    gt=gui.read_text(encoding="utf-8")
    gt=gt.replace('Anno 1503 Auto Trainer V0.11.1 PERMANENT BOOTSTRAP','Anno 1503 Auto Trainer V0.11.2 PERMANENT BOOTSTRAP')
    gt=gt.replace('"version":"0.11.1"','"version":"0.11.2"')
    gt=gt.replace('"version": "0.11.1"','"version": "0.11.2"')
    gt=gt.replace('V0.11.1: Updater-V3-Smoke-Test bestanden; Spiel-/Trainerlogik unverändert …','V0.11.2: Updater V3.1; Build-Helfer unsichtbar + Fortschritt gespiegelt …')
    gui.write_text(gt,encoding="utf-8")

    updater.write_bytes(base64.b64decode(UPDATER_B64))

    (root/'CHANGELOG_V0_11_2.md').write_text(
        '# V0.11.2 - Transactional Updater V3.1\n\n'
        '- Python-, py_compile- und PyInstaller-Unterprozesse laufen unter Windows ohne sichtbare Konsolenfenster.\n'
        '- Update-Fortschritt wird kompakt nach UPDATER_V3_STATUS.json in OneDrive gespiegelt.\n'
        '- Alter Trainer bleibt weiter offen, bis Patch+Compile+Build vollständig erfolgreich sind.\n'
        '- Startup-Healthcheck, automatischer Rollback und Quarantaene fehlgeschlagener identischer Releases bleiben erhalten.\n'
        '- Keine Aenderung an Speed-, Geld-, Waren-, Kalibrierungs- oder Gameplay-Logik.\n',
        encoding='utf-8'
    )
